import{_ as a,o as t,c as i,a5 as n}from"./chunks/framework.DbSlGjul.js";const u=JSON.parse('{"title":"Open call: bimanual manipulation","description":"Contribute HiveBoard assets requiring coordinated manipulation with two hands or end-effectors.","frontmatter":{"description":"Contribute HiveBoard assets requiring coordinated manipulation with two hands or end-effectors."},"headers":[],"relativePath":"contribute/bimanual.md","filePath":"contribute/bimanual.md","lastUpdated":1788882780000}'),o={name:"contribute/bimanual.md"};function r(s,e,l,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="open-call-bimanual-manipulation" tabindex="-1">Open call: bimanual manipulation <a class="header-anchor" href="#open-call-bimanual-manipulation" aria-label="Permalink to &quot;Open call: bimanual manipulation&quot;">​</a></h1><p>We seek functional assets that require <strong>coordinated manipulation by two hands or end-effectors</strong>. The task should specify what each hand does and why both are needed.</p><h2 id="suitable-proposals" tabindex="-1">Suitable proposals <a class="header-anchor" href="#suitable-proposals" aria-label="Permalink to &quot;Suitable proposals&quot;">​</a></h2><p>Possible directions include:</p><ul><li>holding a movable body while turning or releasing another component;</li><li>keeping a spring-loaded mechanism open while inserting a second part;</li><li>aligning two movable components before joining them; and</li><li>applying tension with one hand while the other routes or fastens a flexible element.</li></ul><p>These are examples to discuss with the authors, not a list of approved designs. Explain whether the task requires simultaneous action, a supporting grasp, or a transfer between hands. Two independent tasks performed side by side are insufficient to demonstrate coordination.</p><h2 id="design-requirements" tabindex="-1">Design requirements <a class="header-anchor" href="#design-requirements" aria-label="Permalink to &quot;Design requirements&quot;">​</a></h2><ul><li>Define the role of each hand, including any allowed role exchange.</li><li>Explain which component remains movable and why mounting the asset does not replace the supporting hand.</li><li>Specify the mounting arrangement, occupied cells, clearance, and approach directions.</li><li>State whether either hand may release and regrasp during each stage.</li><li>Define measurable intermediate stages, overall success, and the reset procedure.</li><li>Ensure the camera view shows both end-effectors and the relevant mechanism state.</li><li>Provide the articulated model and demonstrate the physical sequence with both hands visible. State whether the demonstration uses human hands or robots.</li></ul><h2 id="propose-an-asset" tabindex="-1">Propose an asset <a class="header-anchor" href="#propose-an-asset" aria-label="Permalink to &quot;Propose an asset&quot;">​</a></h2><p>Email <a href="mailto:ricardo.godoy@usp.br?subject=HiveBoard%20bimanual%20asset%20proposal" target="_blank" rel="noreferrer">ricardo.godoy@usp.br</a> with:</p><ol><li>Your name, affiliation if applicable, and proposed asset name.</li><li>The task and the role of each hand.</li><li>A sketch showing the mounting arrangement and moving parts.</li><li>The initial state, coordinated sequence, success condition, and reset procedure.</li><li>The files and physical or simulation testing you expect to provide.</li></ol><p><strong>Contact the authors before starting detailed design</strong> to check whether the task requires the intended coordination and fits the benchmark. See <a href="/hivedocs/contribute/requirements">requirements and credit</a> for the complete submission package and authorship eligibility.</p>',12)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
